const userArgs = process.argv.slice(2);

// Check for quiet mode
const QUIET_MODE =
  process.env.CODEX_LAUNCHER_QUIET === "1" ||
  process.env.CODEX_LAUNCHER_QUIET === "true" ||
  process.env.CODEX_LAUNCHER_QUIET === "yes";

// Conditional logging helper
function log(...args) {
  if (!QUIET_MODE) {
    console.log(...args);
  }
}

// Configuration
const CONFIG_DIR = path.join(os.homedir(), ".codex");
const CONFIG_FILE = path.join(CONFIG_DIR, "config");
const RELAY_FILE = path.join(CONFIG_DIR, "relay");
const VERSION_FILE = path.join(CONFIG_DIR, "version.json");

// Path to the interactive relay selector (TUI) vendored in this package
const RELAY_SELECTOR_PATH = path.join(__dirname, "relay-selector", "index.cjs");

// defaultServerUrl is the server url it will use when there's no override
const defaultServerUrl = "https://gaccode.com";

// Extract base domain (host) from a URL-like string
function getHostFromUrl(urlLike) {
  try {
    // Ensure it has a scheme for URL parsing
    const u = new URL(urlLike.match(/^https?:\/\//) ? urlLike : `https://${urlLike}`);
    return u.host;
  } catch {
    return null;
  }
}

// Handle `--pick-relay` CLI flag
// - `codex --pick-relay <host>` writes ~/.codex/relay with the chosen host
// - `codex --pick-relay` launches the interactive selector (TUI)
// Stream relay flags
if (userArgs.includes("--enable-stream-relay")) {
  try {
    enableStreamRelay();
    console.log(color.success("✅ Stream relay enabled"));
    process.exit(0);
  } catch (error) {
    console.error(color.error("❌ Failed to enable stream relay:"), error?.message || error);
    process.exit(1);
  }
}
if (userArgs.includes("--disable-stream-relay")) {
  try {
    disableStreamRelay();
    console.log(color.success("✅ Stream relay disabled"));
    process.exit(0);
  } catch (error) {
    console.error(color.error("❌ Failed to disable stream relay:"), error?.message || error);
    process.exit(1);
  }
}

// Handle `--pick-relay` CLI flag
// - `codex --pick-relay <host>` writes ~/.codex/relay with the chosen host
// - `codex --pick-relay` launches the interactive selector (TUI)
const pickRelayIndex = userArgs.indexOf("--pick-relay");
if (pickRelayIndex !== -1) {
  const maybeHost = userArgs[pickRelayIndex + 1];

  // If a relay host is provided directly, persist it and exit
  if (maybeHost && !maybeHost.startsWith("--")) {
    try {
      if (!fs.existsSync(CONFIG_DIR)) {
        fs.mkdirSync(CONFIG_DIR, { recursive: true });
      }

      let relayData;

      try {
        const url = new URL(maybeHost);
        relayData = {
          scheme: url.protocol.replace(":", ""),
          host: url.hostname,
          port: url.port || undefined,
        };
      } catch {
        // Fallback if it's not a valid URL
        relayData = { host: maybeHost };
      }

      fs.writeFileSync(RELAY_FILE, JSON.stringify(relayData, null, 2));
      console.log(color.success(`✅ Relay set to: ${maybeHost}`));
      process.exit(0);
    } catch (error) {
      console.error(color.error("❌ Failed to set relay:"), error?.message || error);
      process.exit(1);
    }
  } else {
    // Otherwise, spawn the interactive selector
    const baseDomain = getHostFromUrl(process.env.CODEX_SERVER_URL || defaultServerUrl);
    const child = spawn(nodeCmd, [RELAY_SELECTOR_PATH, "--domain", baseDomain], {
      stdio: "inherit",
    });
    child.on("close", (code) => process.exit(code));
    child.on("error", (err) => {
      console.error(color.error("❌ Failed to launch relay selector:"), err?.message || err);
      process.exit(1);
    });
    // Ensure we don't run the rest of the launcher while TUI is active
    return;
  }
}

// Server URL selection: prefer explicit CODEX_SERVER_URL (e.g., https://relay.example.com)
// Fallback to relay file { "host": "host:port", "scheme": "https" }
// Final fallback: defaultServerUrl
function resolveServerUrl() {
  const envUrl = process.env.CODEX_SERVER_URL && process.env.CODEX_SERVER_URL.trim();
  if (envUrl) return envUrl.replace(/\/$/, "");

  try {
    if (fs.existsSync(RELAY_FILE)) {
      const relayData = JSON.parse(fs.readFileSync(RELAY_FILE, "utf8"));
      const host = relayData.host;
      const scheme = relayData.scheme || "https";
      const port = relayData.port || undefined;
      return `${scheme}://${host}${port ? `:${port}` : ""}`.replace(/\/$/, "");
    }
  } catch {}

  return defaultServerUrl;
}

const SERVER_URL = resolveServerUrl();

// Add welcome message with server info
log("\n" + color.boldCyan("🌟 Welcome to Codex!"));
log(color.dim("🔗 Using server: ") + color.bold(SERVER_URL));
const CLIENT_ID = process.env.CLIENT_ID || "Eeghiecheiw5im8Deiv8ugeepiexeequ";
const CLIENT_SECRET =
  process.env.CLIENT_SECRET || "id4eiThiS9Oiluubooph5iefeilooThe4re6ohB3ohNgookai3tie5Ahch8nit9i";
const CALLBACK_HOST = process.env.CALLBACK_HOST || "localhost";
const CALLBACK_PATH = "/oauth/callback";

// Codex package info
const CODEX_VERSION = "0.111.0";
const CODEX_INSTALL_DIR = path.join(os.homedir(), `codex-${CODEX_VERSION}`);

async function ensureCodexInstalled() {
  const installingDir = `${CODEX_INSTALL_DIR}.installing`;

  // Clean up partial installs left by a previous crash or interruption.
  if (fs.existsSync(installingDir)) {
    log("🧹 " + color.warn(`[Codex] Found incomplete install at ${installingDir}, removing...`));
    try {
      fs.rmSync(installingDir, { recursive: true, force: true });
    } catch (e) {
      console.warn(
        "⚠️ " + color.warn(`[Codex] Failed to remove ${installingDir}: ${e?.message || e}`),
      );
    }
  }

  // Check if already installed (presence of bin/codex.js)
  const entry = path.join(CODEX_INSTALL_DIR, "bin", "codex.js");
  if (fs.existsSync(entry)) {
    return CODEX_INSTALL_DIR;
  }

  const googleReachable = await canAccessGoogle();
  log(
    "🧪 " + color.dim("[Codex] Connectivity:"),
    googleReachable ? color.success("reachable") : color.warn("not reachable"),
  );

  // Download tgz to a temp file
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "codex-"));
  const tgzPath = path.join(tmpDir, `codex-${CODEX_VERSION}.tgz`);
  log("⬇️  " + color.info(`Downloading Codex ${CODEX_VERSION}...`));
  await new Promise((resolve, reject) => {
    const out = fs.createWriteStream(tgzPath);
    let codexDownloadUrl = googleReachable
      ? `https://registry.npmjs.org/@openai/codex/-/codex-${CODEX_VERSION}.tgz`
      : `https://vip.123pan.cn/1831946356/links/codex-${CODEX_VERSION}.tgz`;
    if (!googleReachable) {
      log("🛰️ " + color.warn("[Codex] Using codex package mirror"));
    }
    const curlArgs = [
      "--fail", // (-f) Fail on HTTP errors (4xx/5xx) and return a non-zero exit code.
      "--location", // (-L) Automatically follow any HTTP redirects.
      "--silent", // (-s) Don't show the progress meter.
      "--show-error", // (-S) When used with --silent, it will still show an error message if it fails.
      codexDownloadUrl,
    ];

    const curl = spawn("curl", curlArgs);
    curl.stdout.pipe(out);
    out.on("finish", resolve);

    out.on("error", reject); // Catches errors during file writing
    curl.on("error", reject); // Catches errors like `curl` not being installed

    let errorOutput = "";
    curl.stderr.on("data", (data) => {
      errorOutput += data;
    });

    curl.on("close", (code) => {
      if (code !== 0) {
        // A non-zero exit code means the download failed.
        const errorMessage = `Download failed. curl exited with code ${code}. Error: ${errorOutput.trim()}`;
        reject(new Error(errorMessage));
      }
      // If code is 0, success is handled by the 'out.on("finish", resolve)' listener.
    });
  });

  log("📦 " + color.info("Extracting Codex package..."));
  // Extract using system tar
  const { spawnSync } = require("child_process");
  fs.mkdirSync(tmpDir + "/extract");
  const tarRes = spawnSync("tar", ["-xzf", tgzPath, "-C", tmpDir + "/extract"]);
  if (tarRes.status !== 0) {
    throw new Error(`Failed to extract Codex: ${tarRes.stderr?.toString() || "unknown"}`);
  }

  // Move extract/package -> install dir
  const pkgDir = path.join(tmpDir, "extract", "package");
  if (!fs.existsSync(pkgDir)) {
    throw new Error("Invalid Codex archive layout: missing package directory");
  }
  fs.mkdirSync(installingDir, { recursive: true });

  // Recursively move contents
  function copyRecursive(src, dst) {
    const stat = fs.statSync(src);
    if (stat.isDirectory()) {
      if (!fs.existsSync(dst)) fs.mkdirSync(dst);
      for (const f of fs.readdirSync(src)) {
        copyRecursive(path.join(src, f), path.join(dst, f));
      }
    } else {
      fs.copyFileSync(src, dst);
      fs.chmodSync(dst, stat.mode);
    }
  }

  try {
    copyRecursive(pkgDir, installingDir);

    // Install optional dependencies (e.g., @vscode/ripgrep). These are required.
    await ensureDependencies(installingDir, googleReachable);

    if (fs.existsSync(CODEX_INSTALL_DIR)) {
      fs.rmSync(CODEX_INSTALL_DIR, { recursive: true, force: true });
    }
    fs.renameSync(installingDir, CODEX_INSTALL_DIR);
  } catch (err) {
    try {
      if (fs.existsSync(installingDir)) {
        fs.rmSync(installingDir, { recursive: true, force: true });
      }
    } catch {}
    throw err;
  }

  log("✅ " + color.success(`Codex installed at ${CODEX_INSTALL_DIR}`));
  return CODEX_INSTALL_DIR;
}

async function ensureDependencies(dir, googleReachable) {
  // Skip if dependencies already present
  const rgDir = path.join(dir, "node_modules", "@vscode", "ripgrep");
  if (fs.existsSync(rgDir)) {
    log("✅ " + color.success("[Codex] Dependencies already installed, skipping npm install."));
    return;
  }

  const npmCmd = process.platform === "win32" ? "C:\\Users\\xumz\\Desktop\\win\\usb-pack\\runtime\\node\\npm.cmd" : "npm";
  const { spawn } = require("child_process");
  const args = ["install", "--omit=dev"];
  if (!googleReachable) {
    log("🛰️ " + color.warn("[Codex] Using npm mirror registry https://registry.npmmirror.com"));
    args.push("--registry=https://registry.npmmirror.com");
  } else {
    log("🛰️ " + color.dim("[Codex] Using default npm registry"));
  }
  log("🔧 " + color.info("[Codex] Installing dependencies"));
  await new Promise((resolve, reject) => {
    const child = spawn(npmCmd, args, {
      cwd: dir,
      stdio: "inherit",
      shell: process.platform === "win32" ? true : undefined,
    });
    child.on("error", reject);
    child.on("close", (code) => (code === 0 ? resolve() : reject(new Error("npm exited " + code))));
  });
}

function canAccessGoogle() {
  return new Promise((resolve) => {
    // Set a 3-second timeout for the entire function
    const timeout = setTimeout(() => {
      resolve(false);
    }, 3000);

    try {
      // Determine the null device based on the OS for cross-platform compatibility
      const nullDevice = os.platform() === "win32" ? "NUL" : "/dev/null";

      // Construct the curl command
      // --silent: Don't show progress meter or error messages
      // --head: Fetch headers only, making the request faster
      // --connect-timeout: Max time in seconds for the connection to be established
      // --output ${nullDevice}: Redirect output to the null device
      const command = `curl --silent --head --connect-timeout 1.2 --output ${nullDevice} https://www.google.com/generate_204`;

      // Replicating `color.dim` with ANSI escape codes for a similar visual effect
      if (!QUIET_MODE) {
        console.log("🧪 " + "\x1b[2m[Gemini] Testing connectivity to Google with curl\x1b[0m");
      }

      exec(command, (error) => {
        // Clear the timeout if we get a response before 3 seconds
        clearTimeout(timeout);
        // The promise resolves to `true` if the command succeeds (error is null)
        // and `false` if it fails for any reason (e.g., timeout, no route).
        resolve(!error);
      });
    } catch (e) {
      // Clear the timeout and catch synchronous errors during process spawning
      clearTimeout(timeout);
      resolve(false);
    }
  });
}

// Utility: read saved token
function readToken() {
  try {
    if (!fs.existsSync(CONFIG_FILE)) return null;
    const raw = fs.readFileSync(CONFIG_FILE, "utf8");
    const data = JSON.parse(raw);
    if (!data.token) return null;
    return data;
  } catch {
    return null;
  }
}

// Utility: save token
function saveToken(tokenData) {
  try {
    if (!fs.existsSync(CONFIG_DIR)) fs.mkdirSync(CONFIG_DIR, { recursive: true });
    fs.writeFileSync(CONFIG_FILE, JSON.stringify(tokenData, null, 2));
    return true;
  } catch (e) {
    console.error("Failed to save token:", e.message);
    return false;
  }
}

// Utility: verify token against server
async function verifyToken(tokenData) {
  try {
    const res = await fetch(`${SERVER_URL}/api/sso/verify-token`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        token: tokenData.token,
        client_id: CLIENT_ID,
        client_secret: CLIENT_SECRET,
      }),
    });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

// Utility: find an available port by asking the OS for 0
function findAvailablePort() {
  return new Promise((resolve, reject) => {
    const server = http.createServer();
    server.listen(0, CALLBACK_HOST, () => {
      const port = server.address().port;
      server.close(() => resolve(port));
    });
    server.on("error", reject);
  });
}

// Start OAuth flow
async function startOAuthFlow() {
  const CALLBACK_PORT = await findAvailablePort();
  const redirectUri = `http://${CALLBACK_HOST}:${CALLBACK_PORT}${CALLBACK_PATH}`;

  return new Promise((resolve, reject) => {
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    const server = http.createServer(async (req, res) => {
      const sendError = (msg, details = "") => {
        res.statusCode = 400;
        res.setHeader("content-type", "text/html; charset=utf-8");
        const bodyHtml = details
          ? `
          <p class="err">${msg}</p>
          <button onclick="showModal()" class="details-btn">Show Details</button>
          <div id="errorModal" class="modal">
            <div class="modal-content">
              <span class="close" onclick="closeModal()">&times;</span>
              <h2>Error Details</h2>
              <div class="error-details-container">
                <pre class="error-details">${details}</pre>
              </div>
            </div>
          </div>
        `
          : `<p class="err">${msg}</p>`;
        const html = renderHtml({
          title: "OAuth Error",
          heading: "Authentication Error",
          bodyHtml,
        });
        res.end(html);
      };

      try {
        if (req.method !== "GET" || !req.url) {
          res.statusCode = 404;
          res.end("Not found");
          return;
        }
        const url = new URL(req.url, `http://${req.headers.host}`);
        if (url.pathname !== CALLBACK_PATH) {
          res.statusCode = 404;
          res.end("Not found");
          return;
        }

        if (url.searchParams.get("error")) {
          sendError(url.searchParams.get("error"));
          server.close();
          rl.close();
          return reject(new Error(url.searchParams.get("error")));
        }

        const token = url.searchParams.get("token");
        if (!token) {
          sendError("Missing token");
          server.close();
          rl.close();
          return reject(new Error("Missing token"));
        }

        // Verify token with server
        const verifyRes = await fetch(`${SERVER_URL}/api/sso/verify-token`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ token, client_id: CLIENT_ID, client_secret: CLIENT_SECRET }),
        });
        if (!verifyRes.ok) {
          sendError(
            "Token verification failed",
            JSON.stringify(await verifyRes.text()).slice(0, 4000),
          );
          server.close();
          rl.close();
          return reject(new Error("Token verification failed"));
        }
        const data = await verifyRes.json();
        const { userId, email, authenticated } = data || {};
        if (!authenticated) {
          sendError("Not authenticated");
          server.close();
          rl.close();
          return reject(new Error("Not authenticated"));
        }

        const tokenData = { token, userId, email, timestamp: new Date().toISOString() };
        saveToken(tokenData);

        res.statusCode = 200;
        res.setHeader("content-type", "text/html; charset=utf-8");
        const okHtml = renderHtml({
          title: "OAuth Success",
          heading: "✅ You are authenticated!",
          bodyHtml: `
            <p class="ok">Welcome, <strong>${email}</strong></p>
            <p>User ID: <code>${userId}</code></p>
            <p>Token (first 30 chars):<br>
               <code>${token.slice(0, 30)}…</code></p>
            <p>You can close this tab now.</p>`,
        });
        res.end(okHtml);

        rl.close();
        server.close();
        resolve(tokenData);
      } catch (e) {
        try {
          res.statusCode = 500;
          res.setHeader("content-type", "text/html; charset=utf-8");
          res.end(
            renderHtml({
              title: "Internal Error",
              heading: "Unexpected Error",
              bodyHtml: "<p class='err'>Something went wrong.</p>",
            }),
          );
        } catch {}
        server.close();
        rl.close();
        reject(e);
      }
    });

    server.listen(CALLBACK_PORT, CALLBACK_HOST, () => {
      const autoAuthUrl = new URL(`${SERVER_URL}/api/sso/authorize`);
      autoAuthUrl.searchParams.set("client_id", CLIENT_ID);
      autoAuthUrl.searchParams.set("redirect_uri", redirectUri);
      autoAuthUrl.searchParams.set("state", String(Date.now()));

      const manualAuthUrl = new URL(`${SERVER_URL}/api/sso/authorize`);
      manualAuthUrl.searchParams.set("client_id", CLIENT_ID);
      manualAuthUrl.searchParams.set("redirect_uri", redirectUri);
      manualAuthUrl.searchParams.set("state", String(Date.now()));
      manualAuthUrl.searchParams.set("device_flow", "true");

      console.log("\n" + "━".repeat(60));
      console.log("🔐 Authentication Required");
      console.log("━".repeat(60));
      console.log("\n📋 Opening browser for authentication...");
      console.log("\n💡 If authentication completes automatically, you're all set!");
      console.log("   Otherwise, visit this URL manually:");
      console.log(`\n   ${manualAuthUrl.toString()}\n`);
      console.log("⌨️  After manual authentication, you'll receive a code");
      console.log("📝 Paste the code below and press Enter:\n");

      // Try to open browser with automatic flow URL
      setTimeout(() => {
        if (process.platform === "darwin") {
          const { spawn } = require("child_process");
          spawn("open", [autoAuthUrl.toString()]).on("error", () => {});
        }
      }, 100);

      rl.on("line", async (code) => {
        const trimmed = (code || "").trim();
        if (!trimmed) return;
        try {
          const res = await fetch(`${SERVER_URL}/api/sso/verify-code`, {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({
              code: trimmed,
              client_id: CLIENT_ID,
              client_secret: CLIENT_SECRET,
            }),
          });
          if (!res.ok) {
            console.log("Invalid code, try again.");
            return;
          }
          const json = await res.json();
          if (!json.token) {
            console.log("Invalid response, try again.");
            return;
          }
          const tokenData = {
            token: json.token,
            userId: json.userId,
            email: json.email,
            timestamp: new Date().toISOString(),
          };
          saveToken(tokenData);
          console.log("\n✅ Authentication successful!");
          console.log(`👤 Logged in as: ${json.email}`);
          rl.close();
          server.close();
          resolve(tokenData);
        } catch (e) {
          console.log("Error verifying code:", e.message || e);
        }
      });
    });
  });
}

// Entrypoint
(async () => {
  // Support --logout to clear token
  if (userArgs.includes("--logout")) {
    try {
      if (fs.existsSync(CONFIG_FILE)) {
        fs.unlinkSync(CONFIG_FILE);
      }
      console.log(color.success("✅ Logout successful"));
    } catch (error) {
      console.error(color.error("❌ Failed to logout:"), error.message);
      process.exit(1);
    }
    process.exit(0);
  }

  // Check if CODEX_API_KEY is set
  if (process.env.CODEX_API_KEY) {
    log(color.info("💡 CODEX_API_KEY discovered, skipping OAuth"));
    await onAuthenticated({ token: process.env.CODEX_API_KEY, userId: null, email: null });
    return;
  }

  const cached = readToken();
  if (cached) {
    const ok = await verifyToken(cached);
    if (ok) return onAuthenticated(cached);
    log(color.warn("⚠️  Cached token is invalid, re-authenticating..."));
  }
  try {
    const t = await startOAuthFlow();
    return onAuthenticated(t);
  } catch (e) {
    console.error("OAuth flow failed:", e.message || e);
    process.exit(1);
  }
})();

async function onAuthenticated({ token, userId, email }) {
  // Ensure Codex is installed locally for isolation
  log("🔧 " + color.info("[Codex] Ensuring local Codex install..."));
  const installDir = await ensureCodexInstalled();
  log("✅ " + color.success("[Codex] Codex ready at"), installDir);

  // Start stream relay if enabled
  let baseUrl = SERVER_URL;
  if (isStreamRelayEnabled()) {
    streamRelayManager.enabled = true;
    process.env.STREAM_RELAY_QUIET = "1";
    const { port, statsPort } = await streamRelayManager.start(
      __dirname,
      QUIET_MODE,
      log,
      SERVER_URL,
    );
    baseUrl = `http://127.0.0.1:${port}`;
    log(
      color.success("✅ Stream relay enabled, metrics: ") +
        color.boldCyan(`http://127.0.0.1:${statsPort}`),
    );
  }

  // Ensure ~/.codex config files exist and point to our proxy
  log("📝 " + color.info("[Codex] Preparing user config at ~/.codex ..."));
  await ensureCodexUserFiles(baseUrl);
  log("✅ " + color.success("[Codex] User config ready."));

  // Fetch and display announcements (best-effort) - skip in quiet mode
  if (!QUIET_MODE) {
    try {
      log("📢 " + color.info("[Codex] Checking announcements..."));
      const anns = await fetchAnnouncements(SERVER_URL, token);
      if (anns && anns.length > 0) {
        await displayAnnouncements(anns);
      }
    } catch {}
  }

  // Launch Codex CLI with server proxy and bearer token
  const { spawn } = require("child_process");
  const cli = path.join(installDir, "bin", "codex.js");
  const env = {
    ...process.env,
    // Provide bearer token via env specified in config.toml
    CODEX_API_KEY: token,
    USER_ID: String(userId),
    USER_EMAIL: String(email),
  };

  log("🚀 " + color.bold("[Codex] Launching Codex CLI..."));
  log(color.dim("[Codex] Passing CODEX_API_KEY from OAuth token"));
  const child = spawn(nodeCmd, [cli, ...userArgs], {
    stdio: "inherit",
    shell: true,
    env,
  });

  child.on("close", (code) => {
    streamRelayManager.stop();
    process.exit(code ?? 0);
  });
  child.on("error", (err) => {
    console.error("Failed to launch Codex CLI:", err.message || err);
    process.exit(1);
  });
}

async function ensureCodexUserFiles(serverUrl) {
  const dir = path.join(os.homedir(), ".codex");
  const configToml = path.join(dir, "config.toml");
  const authJson = path.join(dir, "auth.json");
  try {
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  } catch {}

  // Update config.toml intelligently
  const baseUrl = `${serverUrl.replace(/\/$/, "")}/codex/v1`;
  const projPath = process.cwd().replace(/\\/g, "/");

  let existingConfig = "";
  let needsUpdate = false;

  try {
    if (fs.existsSync(configToml)) {
      existingConfig = fs.readFileSync(configToml, "utf8");
    }
  } catch {}

  // Parse existing config to understand what needs updating
  const lines = existingConfig.split("\n");
  const newLines = [];
  let inCodexProvider = false;
  let foundCodexProvider = false;
  let foundGlobalSettings = false;
  let hasModelProvider = false;
  let hasModel = false;
  let hasModelReasoning = false;

  // Process existing lines
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    if (line === "[model_providers.codex]") {
      inCodexProvider = true;
      foundCodexProvider = true;
      newLines.push(line);
      continue;
    }

    if (line.startsWith("[") && line !== "[model_providers.codex]") {
      inCodexProvider = false;
    }

    if (inCodexProvider) {
      // Replace codex provider settings
      if (line.startsWith("base_url =")) {
        newLines.push(`base_url = "${baseUrl}"`);
        needsUpdate = true;
      } else if (line.startsWith("name =")) {
        newLines.push('name = "codex"');
      } else if (line.startsWith("wire_api =")) {
        newLines.push('wire_api = "responses"');
      } else if (line.startsWith("env_key =")) {
        newLines.push('env_key = "CODEX_API_KEY"');
      } else if (
        line &&
        !line.startsWith("base_url =") &&
        !line.startsWith("name =") &&
        !line.startsWith("wire_api =") &&
        !line.startsWith("env_key =")
      ) {
        newLines.push(line);
      }
    } else {
      // Check for global settings
      if (line.startsWith("model_provider =")) {
        hasModelProvider = true;
        if (!line.includes('"codex"')) {
          newLines.push('model_provider = "codex"');
          needsUpdate = true;
        } else {
          newLines.push(line);
        }
      } else if (line.startsWith("model =") && !line.includes("model_")) {
        hasModel = true;
        if (!line.includes('"gpt-5')) {
          newLines.push('model = "gpt-5-codex"');
          needsUpdate = true;
        } else {
          newLines.push(line);
        }
      } else if (line.startsWith("model_reasoning_effort =")) {
        hasModelReasoning = true;
        // Keep existing reasoning effort setting
        newLines.push(line);
      } else {
        newLines.push(line);
      }
    }
  }

  // Add missing global settings at the beginning
  const globalSettings = [];
  if (!hasModelProvider) {
    globalSettings.push('model_provider = "codex"');
    needsUpdate = true;
  }
  if (!hasModel) {
    globalSettings.push('model = "gpt-5-codex"');
    needsUpdate = true;
  }
  // if (!hasModelReasoning) {
  //   globalSettings.push("model_reasoning_effort = \"medium\"");
  //   needsUpdate = true;
  // }

  // Add missing codex provider section
  if (!foundCodexProvider) {
    newLines.push("");
    newLines.push("[model_providers.codex]");
    newLines.push('name = "codex"');
    newLines.push(`base_url = "${baseUrl}"`);
    newLines.push('wire_api = "responses"');
    newLines.push('env_key = "CODEX_API_KEY"');
    needsUpdate = true;
  }

  // Construct final config
  let finalConfig;
  if (globalSettings.length > 0) {
    finalConfig = globalSettings.join("\n") + "\n" + newLines.join("\n");
  } else {
    finalConfig = newLines.join("\n");
  }

  // Only write if we need to update
  if (needsUpdate || !fs.existsSync(configToml)) {
    log("📝 " + color.info("[Codex] Updating config:"), configToml);
    try {
      fs.writeFileSync(configToml, finalConfig.trim() + "\n");
    } catch (e) {
      console.error("Failed to write ~/.codex/config.toml:", e.message || e);
    }
  } else {
    log("📝 " + color.dim("[Codex] Config already up to date:"), configToml);
  }

  // Write auth.json with OPENAI_API_KEY null as requested
  const auth = { OPENAI_API_KEY: null };
  log("📝 " + color.info("[Codex] Writing auth:"), authJson);
  try {
    fs.writeFileSync(authJson, JSON.stringify(auth, null, 2));
  } catch (e) {
    console.error("Failed to write ~/.codex/auth.json:", e.message || e);
  }

  // HACK: Preseed version.json so Codex believes it is up to date (disables auto-upgrade banner).
  const fakeVersionInfo = {
    latest_version: CODEX_VERSION,
    last_checked_at: new Date().toISOString(),
  };
  try {
    fs.writeFileSync(VERSION_FILE, `${JSON.stringify(fakeVersionInfo)}\n`);
  } catch (e) {
    console.error("Failed to write ~/.codex/version.json:", e.message || e);
  }
}

// ----- Announcements (simplified) -----
async function fetchAnnouncements(serverUrl, token) {
  try {
    const res = await fetch(`${serverUrl.replace(/\/$/, "")}/api/announcements`, {
      headers: {
        Authorization: `Bearer ${token}`,
        "Accept-Language": "en",
      },
    });
    if (!res.ok) return [];
    const data = await res.json();
    return data.announcements || [];
  } catch {
    return [];
  }
}

async function displayAnnouncements(announcements) {
  if (!announcements || announcements.length === 0) return;

  console.log("\n" + "═".repeat(70));
  console.log("📢 ANNOUNCEMENTS");
  console.log("═".repeat(70));

  announcements.forEach((announcement, index) => {
    const typeIcon =
      {
        info: "ℹ️",
        warning: "⚠️",
        error: "❌",
        success: "✅",
      }[announcement.type] || "ℹ️";

    console.log(`\n${typeIcon} ${announcement.title}`);
    console.log("─".repeat(50));

    // Strip HTML tags for CLI display
    const plainDescription = announcement.description
      .replace(/<[^>]*>/g, "") // Remove HTML tags
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");

    console.log(plainDescription);

    if (index < announcements.length - 1) {
      console.log(); // Add spacing between announcements
    }
  });

  console.log("\n" + "═".repeat(70));

  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
    });

    rl.question("📝 Press Enter to continue...\n\n", () => {
      rl.close();
      resolve();
    });
  });
}
